package com.rp.rhopartner.repository;

public class SqlQuery {
    public static final String SELECT_PARTNER_INFO = "select partner_id,fname,lname,mob,email from rhopartner.partner_info where mob = #{mobileNo};";
    public static final String SELECT_PARTNER_INFO_BY_EMAIL = "select partner_id,fname,lname,mob,email from rhopartner.partner_info where email = #{email};";
    public static final String INSERT_PARTNER_INFO = "INSERT INTO rhopartner.partner_info (partner_id, fname, lname, mob, alt_mob, email, dob, address, pincode, district, city, state, upi_id, acc_holder_name, acc_type, acc_number, ifsc_code, bank_name, branch_name, pan_number, pan_url, aadhar_nubmer, aadhar_url, insert_by, insert_tmstp, update_by, update_tmstp)VALUES(#{partnerId},#{fname}, #{lname}, #{mobileNo},#{altMobileNo},#{email}, #{dob},#{address}, #{pinCode},#{district},#{city},#{state}, #{upiId},#{accHolderName}, #{accType}, #{accNumber}, #{ifscCode},#{bankName}, #{branchName}, #{panNumber}, #{panUrl}, #{aadharNumber},#{aadharUrl}, 'SYSTEM', CURRENT_TIMESTAMP, 'SYSTEM', CURRENT_TIMESTAMP);";
    public static final String SELECT_PARTNER_INFO_BY_PARTNERID = "SELECT partner_id, fname, lname, mob, alt_mob, email, dob, address, pincode, district, city, state, upi_id, acc_holder_name, acc_type, acc_number, ifsc_code, bank_name, branch_name, pan_number, pan_url, aadhar_nubmer, aadhar_url, insert_by, insert_tmstp, update_by, update_tmstp from rhopartner.partner_info where partner_id = #{partnerId};";
    public static final String SELECT_TRANSACTION_INFO = "select partner_id, lifetime_earned_incentive_amt, redeemed_incentive_amt, redemption_available_amt, pending_incentive_amt, is_active FROM rhopartner.transaction_info where partner_id = #{partnerId} and is_active = true;";
    public static final String INSERT_TRANSACTION_INFO = "INSERT INTO rhopartner.transaction_info(partner_id, lifetime_earned_incentive_amt, redeemed_incentive_amt, redemption_available_amt, pending_incentive_amt, is_active, insert_by, insert_tmstp, update_by, update_tmstp) values (#{partnerId}, #{lifetimeEarnedIncentiveAmount}, #{redeemedIncentiveAmount}, #{redemptionAvailableAmount}, #{pendingIncentiveAmount}, #{isActive}, #{insertBy}, CURRENT_TIMESTAMP, #{updateBy}, CURRENT_TIMESTAMP);";
    public static final String SELECT_ORDER_VIEW = "SELECT user_id, ord_id, invoice_id, seller_id, order_at, total_amt, order_amt, order_status, pay_status, addr_id, trk_id, est_delivery_dte, delivered_at, track_status, pay_id,pg_status,rhopartner_commission_pct, rhokart_commission FROM transaction.vw_order_info where invoice_id = #{invoiceId} or ord_id = #{orderId};";
    public static final String SELECT_ORDER_DETAILS = "SELECT user_id, ord_id, invoice_id, seller_id, order_at, total_amt, order_amt, delivered_at FROM transaction.vw_order_info where ord_id = #{orderId};";
    public static final String INSERT_TRANSACTION_DETAIL = " INSERT INTO rhopartner.transaction_detail (tran_id, partner_id, tran_timestamp, tran_type, amount, buyer_name, invoice_id, target_payment_id, description, message, insert_by, insert_tmstp, update_by, update_tmstp,tran_status, order_id) values (#{transactionId}, #{partnerId}, CURRENT_TIMESTAMP, #{transactionType}, #{amount}, #{buyerName}, #{invoiceId}, #{targetPaymentId},#{description}, #{message}, #{insertBy}, CURRENT_TIMESTAMP, #{updateBy}, CURRENT_TIMESTAMP,#{transactionStatus},#{orderId});";
    public static final String UPDATE_TRANSACTION_INFO = "update rhopartner.transaction_info set lifetime_earned_incentive_amt = lifetime_earned_incentive_amt + #{commissionAmount}, redemption_available_amt = redemption_available_amt + #{commissionAmount}, update_tmstp = CURRENT_timestamp , update_by = 'SYSSCAN'  where partner_id = #{partnerId} and is_active = true;";
    public static final String UPDATE_PENDING_INCENTIVE_AMT = "update rhopartner.transaction_info set pending_incentive_amt = pending_incentive_amt + #{commissionAmount}, update_tmstp = CURRENT_TIMESTAMP , update_by = 'SYSSCAN'  where partner_id = #{partnerId} and is_active = true; ";
    public static final String GET_TRANSACTION_DTL_CNT = "select count(*)  from rhopartner.transaction_detail where order_id = #{orderId};";
    public static final String UPDATE_TRANSACTION_INFO_REDEEMED = "update rhopartner.transaction_info  set redemption_available_amt = redemption_available_amt - #{redeemedAmount} , redeemed_incentive_amt = redeemed_incentive_amt + #{redeemedAmount} where partner_id = #{partnerId};";
    public static final String FETCH_TRANSACTION_DETAIL_PARTNERID = "SELECT tran_id, partner_id, tran_timestamp, tran_type, amount, buyer_name, invoice_id, target_payment_id, description, message, insert_by, insert_tmstp, update_by, update_tmstp, tran_status, order_id FROM rhopartner.transaction_detail where partner_id = #{partnerId} order by tran_timestamp desc;";
    public static final String FETCH_TRANSACTION_DETAIL_PARTNERID_WITH_DATE =
            "SELECT tran_id, partner_id, tran_timestamp, tran_type, amount, buyer_name, invoice_id, target_payment_id, description, message, insert_by, insert_tmstp, update_by, update_tmstp, tran_status, order_id " +
                    "FROM rhopartner.transaction_detail " +
                    "WHERE partner_id = #{partnerId} " +
                    "AND insert_tmstp::date BETWEEN #{startDate} AND #{endDate} " +
                    "ORDER BY tran_timestamp DESC;";

    public static final String UPDATE_PARTNER_DETAIL = "UPDATE rhopartner.partner_info SET fname=#{fname}, lname=#{lname}, mob=#{mob}, alt_mob=#{altMob}, email=#{email}, dob=#{dob}, address=#{address}, pincode=#{pincode}, district=#{district}, city=#{city}, state=#{state}, upi_id=#{upiId}, acc_holder_name=#{accHolderName}, acc_type=#{accType}, acc_number=#{accNumber}, ifsc_code=#{ifscCode}, bank_name=#{bankName}, branch_name=#{branchName}, pan_number=#{panNumber}, pan_url=#{panUrl}, aadhar_nubmer=#{aadharNumber}, aadhar_url=#{aadharUrl},  update_by='System', update_tmstp= CURRENT_TIMESTAMP WHERE partner_id=#{partnerId};";
    public static final String SELECT_ORDER_DETAIL_FROM_VW_ORDER_FULLFILL = "SELECT invoice_id,fname,total_amt,order_at,update_tmstp FROM transaction.vw_order_fulfill where ord_id = #{orderId};";
    public static final String SELECT_ORDERED_ITEM_DETAIL_FROM_ORDER_DETAIL = "SELECT quantity, sku_id, sku_nme, total_amt from transaction.order_detail where ord_id = #{orderId};";
}